use crate::solver::SolverProblem;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

// The transactional certificate layer described in PROTOCOL.md.
//
// The committed state is always legal: the initial configuration is checked at
// construction time and only proposals whose four exact proposed-state
// violation counts are all zero are committed. Rejected proposals (including
// stale revisions) never touch any committed value.
//
// A template footprint is the set of cache-bearing nodes on all shortest
// routes of its endpoints; the supplied topology module already materialises
// those node sets in SolverProblem::demands. The template domain is the
// demand merge class when present (Dragonfly source/target-group scope) and
// otherwise the source merge group containing the demand source.

const FP_WORDS: usize = 6; // num_nodes <= 343 < 6 * 64

#[derive(Clone, Copy)]
struct TaskEdit {
    template: u32,
    group: u32,
    weight: u64,
    class: u64,
    pinned: bool,
}

struct TaskDelta {
    task: usize,
    template0: u32,
    template1: u32,
    group0: u32,
    group1: u32,
    weight0: u64,
    weight1: u64,
    class0: u64,
    class1: u64,
    pinned0: bool,
    pinned1: bool,
}

pub struct Ledger {
    num_nodes: usize,
    footprint: Vec<[u64; FP_WORDS]>,
    domain: Vec<u64>,
    // committed task fields
    task_template: Vec<u32>,
    task_group: Vec<u32>,
    task_weight: Vec<u64>,
    task_class: Vec<u64>,
    task_pinned: Vec<bool>,
    // committed group fields
    group_quota: Vec<u64>,
    group_budget: Vec<u64>,
    // committed group aggregates
    group_count: Vec<i64>,
    group_load: Vec<u64>,
    group_fp_size: Vec<u32>,
    group_domain: Vec<u64>,
    group_class: Vec<u64>,
    group_pinned: Vec<i64>,
    group_cover: Vec<Vec<u32>>,
    // committed node fields and aggregates
    node_capacity: Vec<u64>,
    node_usage: Vec<u64>,
    // committed certificate totals
    total_active: u64,
    total_slots: u64,
    total_weight: u64,
    total_pins: u64,
    revision: u64,
}

fn fp_nodes(bits: &[u64; FP_WORDS]) -> impl Iterator<Item = usize> + '_ {
    (0..FP_WORDS).flat_map(move |w| {
        let mut word = bits[w];
        std::iter::from_fn(move || {
            if word == 0 {
                return None;
            }
            let b = word.trailing_zeros() as usize;
            word &= word - 1;
            Some(w * 64 + b)
        })
    })
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        let num_groups = quotas.len();
        if budgets.len() != num_groups || capacities.len() != n {
            return Err("invalid".into());
        }
        let num_templates = problem.demands.len();
        let mut source_index = vec![usize::MAX; n];
        for (gi, nodes) in problem.source_merge_groups.iter().enumerate() {
            for &node in nodes {
                if node < n {
                    source_index[node] = gi;
                }
            }
        }
        let mut footprint = vec![[0u64; FP_WORDS]; num_templates];
        let mut domain = vec![0u64; num_templates];
        for (ti, demand) in problem.demands.iter().enumerate() {
            for &node in &demand.footprint {
                if node < n {
                    footprint[ti][node / 64] |= 1u64 << (node % 64);
                }
            }
            domain[ti] = match &problem.demand_merge_classes {
                Some(classes) if ti < classes.len() => classes[ti] as u64,
                _ => {
                    if demand.src < n && source_index[demand.src] != usize::MAX {
                        source_index[demand.src] as u64
                    } else {
                        demand.src as u64
                    }
                }
            };
        }
